const REASON={lp:TX('effects.lpHit0'),deckout:TX('effects.hadDrawFromEmptyDeck'),concede:'conceded',turns:TX('effects.turnMaxTurnsEnded',{MAX_TURNS:R.MAX_TURNS})};function endDuel(state,winner,reason){if(state.winner!==null&&state.winner!==undefined)return;state.winner=winner;state.reason=reason;let text;if(winner==='draw')text=reason==='turns'?TX('effects.turnMaxTurnsEndedDuel',{MAX_TURNS:R.MAX_TURNS}):TX('effects.bothLpHit0Duel');else{const loser=1-winner;text=reason==='lp'?TX('effects.pnameSLpHit0',{pname:pname(state,loser),pname2:pname(state,winner)})
:reason==='deckout'?TX('effects.pnameHadDrawFromEmpty',{pname:pname(state,loser),pname2:pname(state,winner)})
:reason==='concede'?TX('effects.pnameConcedesPname2Wins',{pname:pname(state,loser),pname2:pname(state,winner)})
:TX('effects.pnameWinsV',{pname:pname(state,winner),v:REASON[reason]||reason});}DS.emit(state,{type:'over',winner,reason,text});}function checkLp(state){if(state.winner!==null&&state.winner!==undefined)return;const a=state.players[0].lp<=0,b=state.players[1].lp<=0;if(a&&b)endDuel(state,'draw','lp');else if(a)endDuel(state,1,'lp');else if(b)endDuel(state,0,'lp');}
